// frontend/src/nodes/BaseNode.jsx
import React from 'react';
import { Handle, Position } from 'reactflow'; // Import Position from reactflow

// Color mapping for each node type
const NODE_COLORS = {
  customInput: { header: '#0ea5e9', bg: '#f0f9ff' },
  llm: { header: '#8b5cf6', bg: '#f3e8ff' },
  customOutput: { header: '#ec4899', bg: '#fdf2f8' },
  text: { header: '#10b981', bg: '#f0fdf4' },
  math: { header: '#f59e0b', bg: '#fffbeb' },
  api: { header: '#3b82f6', bg: '#dbeafe' },
  condition: { header: '#ef4444', bg: '#fef2f2' },
  csv: { header: '#059669', bg: '#f0fdf4' },
  custom: { header: '#6b7280', bg: '#f3f4f6' },
};

const BaseNode = ({ data, type }) => {
  const { label, handles = [], content } = data; // Destructure handles from data
  const colors = NODE_COLORS[type] || NODE_COLORS.custom;

  // DEBUG: Log the handles received
  console.log(`[BaseNode] Type: ${type}, Received handles:`, handles);

  return (
    <div
      style={{
        width: '220px',
        borderRadius: '8px',
        border: `1px solid ${colors.header}`,
        backgroundColor: colors.bg,
        boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
        fontFamily: 'Inter, sans-serif',
        position: 'relative', // Needed for absolute positioning if handles were positioned absolutely
      }}
    >
      <div
        style={{
          padding: '8px 12px',
          backgroundColor: colors.header,
          color: 'white',
          fontSize: '13px',
          fontWeight: 600,
          borderBottom: `1px solid ${colors.header}`,
        }}
      >
        {label || type}
      </div>
      <div style={{ padding: '10px 12px', fontSize: '13px', color: '#374151' }}>
        {content}
      </div>
      {/* Iterate through the handles array passed from the specific node component */}
      {handles.map((handle) => {
        console.log(`[BaseNode] Rendering handle:`, handle); // DEBUG: Log each handle being rendered

        // Convert the string position ('left', 'right') to the reactflow Position enum
        let positionEnum;
        if (handle.position === 'left') {
          positionEnum = Position.Left;
        } else if (handle.position === 'right') {
          positionEnum = Position.Right;
        } else if (handle.position === 'top') {
          positionEnum = Position.Top;
        } else if (handle.position === 'bottom') {
          positionEnum = Position.Bottom;
        } else {
          // Default or handle invalid positions
          console.warn(`[BaseNode] Invalid handle position: ${handle.position}. Defaulting to Left.`);
          positionEnum = Position.Left; // Or maybe Position.Right
        }

        // Determine background color based on handle type if not overridden
        const handleBackgroundColor = handle.style?.background || colors.header;

        // Optional: Add a visual indicator for debugging handle placement
        let indicatorStyle = {
          position: 'absolute',
          width: '8px',
          height: '8px',
          background: 'red', // Use a contrasting color
          border: '1px solid black',
          fontSize: '8px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'white',
          fontWeight: 'bold',
          zIndex: 10, // Ensure it's visible
        };

        if (positionEnum === Position.Left) {
          indicatorStyle.left = '-12px'; // Slightly outside the border
          indicatorStyle.top = '50%'; // Center vertically, adjust if multiple handles needed
          indicatorStyle.transform = 'translateY(-50%)'; // Align center vertically
        } else if (positionEnum === Position.Right) {
          indicatorStyle.right = '-12px'; // Slightly outside the border
          indicatorStyle.top = '50%'; // Center vertically
          indicatorStyle.transform = 'translateY(-50%)'; // Align center vertically
        } else if (positionEnum === Position.Top) {
          indicatorStyle.top = '-12px'; // Slightly outside the border
          indicatorStyle.left = '50%'; // Center horizontally
          indicatorStyle.transform = 'translateX(-50%)'; // Align center horizontally
        } else if (positionEnum === Position.Bottom) {
          indicatorStyle.bottom = '-12px'; // Slightly outside the border
          indicatorStyle.left = '50%'; // Center horizontally
          indicatorStyle.transform = 'translateX(-50%)'; // Align center horizontally
        }

        return (
          <React.Fragment key={handle.id}> {/* Use Fragment to group Handle and indicator */}
            <Handle
              type={handle.type} // 'target' or 'source' - crucial for connection direction
              position={positionEnum} // Use the converted Position enum
              id={handle.id} // The specific ID for the handle
              style={{
                // Apply styling
                background: handleBackgroundColor,
                border: handle.style?.border || '2px solid white',
                // You can add other styles here if needed
                // e.g., width, height, zIndex
              }}
            />
            {/* Temporary visual indicator for debugging */}
            <div style={indicatorStyle}>
              {handle.id.charAt(0).toUpperCase()} {/* Display first letter of handle ID */}
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );
};

export default BaseNode;
